package tenantdb

import (
	"context"
	"crypto/tls"
	"fmt"
	"regexp"
	"strings"
	"sync"

	"github.com/go-ldap/ldap/v3"
)

// TenantResolver resolves database connection parameters via LDAP directory
type TenantResolver struct {
	mu        sync.RWMutex
	conn      *ldap.Conn
	baseDN    string
	bindDN    string
	bindPass  string
	ldapURL   string
	cache     map[string]*TenantConfig
	sanitizer *InputSanitizer
}

type TenantConfig struct {
	DSN       string
	MaxConns  int
	ReadOnly  bool
	Isolation string
}

// InputSanitizer provides LDAP injection protection
type InputSanitizer struct {
	// allowedChars matches valid tenant identifiers
	allowedChars *regexp.Regexp
	// dnEscaper handles DN component escaping
	dnEscaper *strings.Replacer
	// filterEscaper handles search filter escaping
	filterEscaper *strings.Replacer
}

func NewInputSanitizer() *InputSanitizer {
	return &InputSanitizer{
		allowedChars: regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]{0,62}$`),
		dnEscaper: strings.NewReplacer(
			"\\", "\\\\",
			",", "\\,",
			"+", "\\+",
			"\"", "\\\"",
			"<", "\\<",
			">", "\\>",
			";", "\\;",
			"=", "\\=",
		),
		filterEscaper: strings.NewReplacer(
			"\\", "\\5c",
			"*", "\\2a",
			"(", "\\28",
			")", "\\29",
			"\x00", "\\00",
		),
	}
}

// SanitizeFilter escapes special characters for LDAP search filters
func (s *InputSanitizer) SanitizeFilter(input string) string {
	return s.filterEscaper.Replace(input)
}

// ValidateTenantID checks if tenant ID matches allowed pattern
func (s *InputSanitizer) ValidateTenantID(id string) bool {
	return s.allowedChars.MatchString(id)
}

// SanitizeDN escapes special characters for DN components
func (s *InputSanitizer) SanitizeDN(input string) string {
	return s.dnEscaper.Replace(input)
}

func NewTenantResolver(ldapURL, baseDN, bindDN, bindPass string) (*TenantResolver, error) {
	tr := &TenantResolver{
		baseDN:    baseDN,
		bindDN:    bindDN,
		bindPass:  bindPass,
		ldapURL:   ldapURL,
		cache:     make(map[string]*TenantConfig),
		sanitizer: NewInputSanitizer(),
	}
	if err := tr.connect(); err != nil {
		return nil, err
	}
	return tr, nil
}

func (tr *TenantResolver) connect() error {
	conn, err := ldap.DialURL(tr.ldapURL, ldap.DialWithTLSConfig(&tls.Config{MinVersion: tls.VersionTLS12}))
	if err != nil {
		return fmt.Errorf("ldap dial: %w", err)
	}
	if err := conn.Bind(tr.bindDN, tr.bindPass); err != nil {
		conn.Close()
		return fmt.Errorf("ldap bind: %w", err)
	}
	tr.conn = conn
	return nil
}

// ResolveTenant looks up tenant configuration from LDAP directory
func (tr *TenantResolver) ResolveTenant(ctx context.Context, tenantID string, subOrg string) (*TenantConfig, error) {
	tr.mu.RLock()
	cacheKey := tenantID + "/" + subOrg
	if cfg, ok := tr.cache[cacheKey]; ok {
		tr.mu.RUnlock()
		return cfg, nil
	}
	tr.mu.RUnlock()

	// Validate tenant ID with strict allowlist
	if !tr.sanitizer.ValidateTenantID(tenantID) {
		return nil, fmt.Errorf("invalid tenant ID format: %s", tenantID)
	}

	// Build the search filter using sanitized components
	filter := tr.buildSearchFilter(tenantID, subOrg)

	searchDN := fmt.Sprintf("ou=tenants,%s", tr.baseDN)
	req := ldap.NewSearchRequest(
		searchDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		1, // sizeLimit
		10, // timeLimit
		false,
		filter,
		[]string{"dbConnectionString", "dbMaxConnections", "dbReadOnly", "dbIsolationLevel"},
		nil,
	)

	result, err := tr.conn.Search(req)
	if err != nil {
		return nil, fmt.Errorf("ldap search: %w", err)
	}

	if len(result.Entries) == 0 {
		return nil, fmt.Errorf("tenant not found: %s", tenantID)
	}

	entry := result.Entries[0]
	cfg := &TenantConfig{
		DSN:       entry.GetAttributeValue("dbConnectionString"),
		Isolation: entry.GetAttributeValue("dbIsolationLevel"),
	}

	tr.mu.Lock()
	tr.cache[cacheKey] = cfg
	tr.mu.Unlock()

	return cfg, nil
}

// buildSearchFilter constructs an LDAP filter for tenant lookup
// tenantID is validated via allowlist regex before reaching here
// subOrg is sanitized via filter escaping
func (tr *TenantResolver) buildSearchFilter(tenantID string, subOrg string) string {
	// tenantID already validated by allowlist - safe to use directly
	// subOrg needs escaping as it comes from request context
	escapedSubOrg := tr.sanitizer.SanitizeFilter(subOrg)

	if escapedSubOrg == "" {
		return fmt.Sprintf("(&(objectClass=tenantEntry)(cn=%s))", tenantID)
	}

	// Multi-level filter: tenant within specific organizational unit
	return fmt.Sprintf("(&(objectClass=tenantEntry)(cn=%s)(ou=%s))", tenantID, escapedSubOrg)
}

// ResolveWithAttributes performs a lookup with additional attribute filter
func (tr *TenantResolver) ResolveWithAttributes(ctx context.Context, tenantID string, attrs map[string]string) (*TenantConfig, error) {
	if !tr.sanitizer.ValidateTenantID(tenantID) {
		return nil, fmt.Errorf("invalid tenant ID format")
	}

	filterParts := []string{
		"(objectClass=tenantEntry)",
		fmt.Sprintf("(cn=%s)", tenantID),
	}

	// Allowlist for attribute keys that can be used in filters
	allowedKeys := map[string]bool{
		"ou": true, "l": true, "st": true, "c": true, "description": true,
	}

	for key, value := range attrs {
		if !allowedKeys[key] {
			return nil, fmt.Errorf("attribute key not allowed: %s", key)
		}
		safeValue := tr.sanitizer.SanitizeFilter(value)
		filterParts = append(filterParts, fmt.Sprintf("(%s=%s)", key, safeValue))
	}

	filter := fmt.Sprintf("(&%s)", strings.Join(filterParts, ""))

	searchDN := fmt.Sprintf("ou=tenants,%s", tr.baseDN)
	req := ldap.NewSearchRequest(
		searchDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		1,
		10,
		false,
		filter,
		[]string{"dbConnectionString", "dbMaxConnections", "dbReadOnly", "dbIsolationLevel"},
		nil,
	)

	result, err := tr.conn.Search(req)
	if err != nil {
		return nil, fmt.Errorf("ldap search: %w", err)
	}

	if len(result.Entries) == 0 {
		return nil, fmt.Errorf("tenant not found")
	}

	entry := result.Entries[0]
	return &TenantConfig{
		DSN:       entry.GetAttributeValue("dbConnectionString"),
		Isolation: entry.GetAttributeValue("dbIsolationLevel"),
	}, nil
}
